package org.firstinspires.ftc.teamcode;

import com.pedropathing.algorithm.Foresight;
import com.pedropathing.follower.Follower;
import com.pedropathing.math.Pose;
import com.pedropathing.paths.Path;
import com.qualcomm.robotcore.eventloop.opmode.Autonomous;
import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.util.ElapsedTime;
import org.firstinspires.ftc.teamcode.pedro.Constants;

/**
 * Autonomous for "BIOBUZZ red auto", generated by Deck Driver Station for Pedro Pathing 3.0.2
 * (com.pedropathing:revhub:3.0.2, FTC SDK 12.0.0). Needs a TeamCode built from the Pedro Pathing
 * Quickstart: its pedro/Constants.java must return your tuned Follower from Constants.create(hardwareMap).
 *
 * Files: LunalaRedPaths.java (the paths), this OpMode, RouteActions.java (action slots, regenerated), Mechanisms.java (your intake/shooter from Deck)
 * and RobotActions.java (YOUR action code; created once, keep your edits).
 *
 * Robot readiness:
 *  [x] Compiles: Deck's export check compiles this generator's output against FTC SDK 12.0.0 and Pedro Pathing 3.0.2 (tools/simulation/check-ftc-sdk.cjs).
 *  [x] Runs with Pedro’s Follower: Deck’s development tests run this generator’s output with Pedro Pathing 3.0.2’s own Follower, Mecanum drivetrain and Pinpoint/OTOS localizer on the virtual Control Hub (tests/sim-pedro-runtime.test.cjs).
 *  [x] Path geometry: Coordinates, curves and headings are the ones the planner checked for clearance; unit tests compare them.
 *  [ ] Pedro setup: pedro/Constants.java must build your Follower: drive motor names and directions, localizer and its offsets. DeckStarterConstants.java (written beside it for mecanum robots with a Pinpoint or OTOS) holds estimated starting values: return DeckStarterConstants.create(h) from Constants.create while you tune.
 *  [ ] Tuning: Run the Quickstart tuners (localizer, drivetrain, Foresight) on your robot. Deck cannot tune a real robot.
 *  [ ] Starting pose: Place the robot exactly at START before INIT; the localizer is set to it at START.
 *  [ ] Actions: Mechanisms.java drives the intake/shooter set up in Deck; check device names and directions. Other actions need code in RobotActions.java.
 *  [ ] Real-world test: Drive it on a practice field at low speed first. Simulation and compilation do not prove the robot will follow the path.
 */
@Autonomous(name = "BIOBUZZ red auto (Pedro)", group = "Deck Driver Station")
public class LunalaRedPedro extends LinearOpMode {
    private Follower follower;
    private RouteActions actions;
    private final RouteActions.Step step = new RouteActions.Step();

    @Override
    public void runOpMode() throws InterruptedException {
        follower = Constants.create(hardwareMap);
        if (follower == null) {
            // The Quickstart's Constants.create returns null until Pedro Pathing is set up and tuned.
            telemetry.addLine("Pedro Pathing is not set up: Constants.create(hardwareMap) returned null.");
            telemetry.addLine("Fill in pedro/Constants.java (drivetrain, localizer, Foresight) and tune it first.");
            telemetry.update();
            waitForStart();
            return;
        }
        actions = new RobotActions();
        actions.init(hardwareMap, telemetry);
        Path[] legs = LunalaRedPaths.legs();
        follower.setPose(LunalaRedPaths.START);
        while (opModeInInit()) {
            follower.update();
            Pose p = follower.pose();
            telemetry.addData("Route", legs.length + " legs");
            telemetry.addData("Place robot at", "x %.1f  y %.1f  heading %.0f", LunalaRedPaths.START.x(), LunalaRedPaths.START.y(), Math.toDegrees(LunalaRedPaths.START.heading()));
            telemetry.addData("Localizer", "x %.1f  y %.1f  heading %.0f", p.x(), p.y(), Math.toDegrees(p.heading()));
            if (!(follower.algorithm() instanceof Foresight)) telemetry.addLine("Speed limits per path need the Foresight algorithm; driving at full path speed.");
            telemetry.update();
        }
        if (isStopRequested()) {
            actions.stop();
            return;
        }
        // The robot sits at the starting pose at START: forget any drift picked up during INIT.
        follower.setPose(LunalaRedPaths.START);
        try {
            ElapsedTime timer = new ElapsedTime(), movingTimer = new ElapsedTime();
            double plannedHeading = LunalaRedPaths.START.heading();
            int movingPath = 0;
            boolean movingDone = true, movingFirst = false;
            for (int i = 0; i < legs.length && opModeIsActive(); i++) {
                if (LunalaRedPaths.MAX_PATH_SPEED[i] <= 0) {
                    // Zero motor power in Deck: stay stopped until the end of autonomous.
                    stopDriving();
                    while (opModeIsActive()) { report(i, legs.length, "Zero motor power: stopped"); idle(); }
                    break;
                }
                // Turn only where the plan changes heading, not to chase small drift.
                if (Math.abs(angle(LunalaRedPaths.START_HEADING[i] - plannedHeading)) > Math.toRadians(0.5)) turnTo(LunalaRedPaths.START_HEADING[i], i, legs.length);
                // An action path's action starts with the path and may span several legs of it.
                String moving = LunalaRedPaths.MOVING_ACTIONS[i];
                if (!moving.isEmpty() && LunalaRedPaths.PATH[i] != movingPath) {
                    movingPath = LunalaRedPaths.PATH[i];
                    movingDone = false;
                    movingFirst = true;
                    movingTimer.reset();
                }
                Pose end = legs[i].endPose();
                follower.follow(limited(legs[i], LunalaRedPaths.MAX_PATH_SPEED[i]));
                step.wait = 0;
                while (opModeIsActive() && follower.following()) {
                    follower.update();
                    if (!moving.isEmpty() && !movingDone) {
                        // A set time runs the action from the start of its path; the last call stops it.
                        double t = movingTimer.seconds();
                        boolean over = LunalaRedPaths.MOVING_SECONDS[i] > 0 && t >= LunalaRedPaths.MOVING_SECONDS[i];
                        step.duration = LunalaRedPaths.MOVING_SECONDS[i];
                        step.cell = LunalaRedPaths.MOVING_CELL[i];
                        movingDone = act(moving, t, movingFirst, over, true, LunalaRedPaths.PIN[i]) || over;
                        movingFirst = false;
                    }
                    report(i, legs.length, moving.isEmpty() ? "Driving" : "Action path");
                    if (LunalaRedPaths.THROUGH[i] && near(end, 1.5) && follower.completion() > 0.9) break;
                }
                boolean pathEnds = i == legs.length - 1 || LunalaRedPaths.PATH[i + 1] != movingPath || LunalaRedPaths.MOVING_ACTIONS[i + 1].isEmpty();
                if (!moving.isEmpty() && pathEnds) {
                    // The path is over: one last call so the action can stop its mechanisms.
                    if (!movingDone) { step.duration = LunalaRedPaths.MOVING_SECONDS[i]; act(moving, movingTimer.seconds(), movingFirst, true, true, LunalaRedPaths.PIN[i]); }
                    movingDone = true;
                    movingPath = 0;
                }
                plannedHeading = end.heading();
                if (LunalaRedPaths.THROUGH[i]) continue;
                // Pedro holds the end pose once the path is done; wait (at most 3 s) for the robot to settle on it.
                timer.reset();
                while (opModeIsActive() && timer.seconds() < 3 && !(near(end, 0.75) && follower.velocity().linSpeed() < 0.5)) {
                    follower.update();
                    report(i, legs.length, "Settling");
                }
                if (!Double.isNaN(LunalaRedPaths.TURN_AFTER[i])) {
                    turnTo(LunalaRedPaths.TURN_AFTER[i], i, legs.length);
                    plannedHeading = LunalaRedPaths.TURN_AFTER[i];
                }
                // At the end point: pause, then run the action for its set time (or until it reports done), then drive on.
                timer.reset();
                while (opModeIsActive() && timer.seconds() < LunalaRedPaths.WAIT_SECONDS[i]) {
                    follower.update();
                    report(i, legs.length, "Pause");
                }
                String action = LunalaRedPaths.ACTIONS[i];
                step.wait = LunalaRedPaths.WAIT_SECONDS[i];
                step.duration = LunalaRedPaths.ACTION_SECONDS[i];
                step.cell = LunalaRedPaths.ACTION_CELL[i];
                boolean done = action.isEmpty(), first = true;
                timer.reset();
                while (opModeIsActive() && !done) {
                    follower.update();
                    double t = timer.seconds();
                    boolean over = LunalaRedPaths.ACTION_SECONDS[i] > 0 && t >= LunalaRedPaths.ACTION_SECONDS[i];
                    done = act(action, t, first, over, false, LunalaRedPaths.PIN[i]) || over;
                    first = false;
                    report(i, legs.length, "Action");
                }
            }
            // Route finished: hold the last pose until the autonomous period ends. Never restarts a leg.
            while (opModeIsActive()) {
                follower.update();
                report(legs.length - 1, legs.length, "Done");
            }
        } finally {
            // Stop the drive first: an error in a mechanism's stop code must not leave the wheels turning.
            try {
                stopDriving();
            } finally {
                actions.stop();
            }
        }
    }

    /** Applies the leg's speed limit through Foresight's maxPathSpeed, for this path only. */
    private Path limited(Path path, double speed) {
        if (speed >= 1 || !(follower.algorithm() instanceof Foresight)) return path;
        return path.with(((Foresight) follower.algorithm()).config.maxPathSpeed.at(speed));
    }

    /** Turn in place: done when the heading has stayed within 1.5 degrees for 0.15 s (at most 5 s). */
    private void turnTo(double heading, int leg, int legs) {
        Pose here = follower.pose();
        follower.hold(new Pose(here.x(), here.y(), heading));
        ElapsedTime timer = new ElapsedTime();
        double settledSince = -1;
        while (opModeIsActive() && timer.seconds() < 5) {
            follower.update();
            report(leg, legs, "Turning");
            boolean on = Math.abs(angle(heading - follower.pose().heading())) < Math.toRadians(1.5);
            if (!on) settledSince = -1;
            else if (settledSince < 0) settledSince = timer.seconds();
            else if (timer.seconds() - settledSince > 0.15) break;
        }
    }

    /** Stops the drive at once (Follower.stop alone zeroes the motors on its next update). */
    private void stopDriving() {
        follower.stop();
        follower.drivetrain.stop();
    }

    private boolean act(String name, double elapsed, boolean first, boolean last, boolean moving, int pin) {
        step.elapsed = elapsed;
        step.first = first;
        step.last = last;
        step.moving = moving;
        step.pin = pin;
        step.pose = follower.pose();
        telemetry.addData("Action", name);
        return actions.run(name, step);
    }

    private boolean near(Pose target, double inches) {
        Pose p = follower.pose();
        return Math.hypot(p.x() - target.x(), p.y() - target.y()) < inches;
    }

    private static double angle(double radians) {
        return Math.atan2(Math.sin(radians), Math.cos(radians));
    }

    private void report(int leg, int legs, String phase) {
        Pose p = follower.pose();
        telemetry.addData("Leg", (leg + 1) + " of " + legs);
        telemetry.addData("Phase", phase);
        telemetry.addData("x", "%.1f", p.x());
        telemetry.addData("y", "%.1f", p.y());
        telemetry.addData("heading", "%.1f", Math.toDegrees(p.heading()));
        telemetry.update();
    }
}
